import re; import string; from datetime import date; from decimal import Decimal; from pathlib import Path; from unittest.mock import AsyncMock, patch; from uuid import uuid4; import pytest; from sqlalchemy import text; from sqlalchemy.ext.asyncio import AsyncSession; from src.extraction import BankStatementStatus, DocumentSource, ExtractionMethod, ParseJob, StatementEvidenceType; from src.extraction.extension.result_contract import build_statement_extraction_result; from src.extraction.extension.service import ExtractionService; from src.extraction.orm.statement_summary import StatementSummary; from src.ledger import Account, AccountType; from tests.factories import StatementSummaryFactory; from tests.statement_ingestion import parse_and_load_statement_projection
async def _make_statement_account(db: AsyncSession, user_id) -> Account: account = Account(user_id=user_id, name=f'DBS Statement {uuid4().hex[:8]}', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.flush(); return account
class TestDirtyAccountLast4Integration:
    DIRTY_AI_RESPONSES = [pytest.param('553-3', '5533', id='hyphenated-5-chars'), pytest.param('ABCDE', 'BCDE', id='5-alpha-takes-last4'), pytest.param('12号34', '1234', id='unicode-stripped'), pytest.param('1234-5678-9012', '9012', id='long-account-number'), pytest.param('----', None, id='only-hyphens'), pytest.param('', None, id='empty-string'), pytest.param(None, None, id='null-value'), pytest.param('  5 5 3 3  ', '5533', id='spaces-stripped'), pytest.param('X', 'X', id='single-char-preserved'), pytest.param('AB', 'AB', id='two-chars-preserved')]
    @pytest.mark.parametrize('ai_value,expected_sanitized', DIRTY_AI_RESPONSES)
    async def test_parse_document_sanitizes_account_last4(self, ai_value, expected_sanitized):
        service = ExtractionService(); mock_data = {'institution': 'DBS', 'account_last4': ai_value, 'currency': 'SGD', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '1000.00', 'closing_balance': '1100.00', 'transactions': [{'date': '2025-01-15', 'description': 'Salary', 'amount': '100.00', 'direction': 'IN'}]}
        with patch.object(service, 'extract_financial_data', new=AsyncMock(return_value=mock_data)): result = await service.parse_document(DocumentSource.resolve(path=Path('/tmp/test_sanitize.pdf'), content=b'dummy'), institution='DBS', user_id=uuid4())
        if expected_sanitized is not None: assert result.account_last4 == expected_sanitized; assert len(expected_sanitized) <= 4; assert all((c in string.ascii_letters + string.digits for c in expected_sanitized))
        else: assert result.account_last4 is None
    async def test_dirty_account_last4_persists_to_db(self, db, test_user):
        service = ExtractionService(); account = await _make_statement_account(db, test_user.id); mock_data = {'institution': 'DBS', 'account_last4': '553-3', 'currency': 'SGD', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '1000.00', 'closing_balance': '1100.00', 'transactions': [{'date': '2025-01-15', 'description': 'Test', 'amount': '100.00', 'direction': 'IN'}]}; uid = test_user.id
        with patch.object(service, 'extract_financial_data', new=AsyncMock(return_value=mock_data)): result, stmt, _ = await parse_and_load_statement_projection(service, db=db, source=DocumentSource.resolve(path=Path('/tmp/test_persist.pdf'), content=b'dummy'), institution='DBS', user_id=uid, account_id=account.id)
        await db.commit(); saved = await db.get(StatementSummary, stmt.id); assert saved is not None; assert saved.account_last4 == '5533'; assert len(saved.account_last4) <= 4
    async def test_parse_document_without_account_stays_parsed_before_approval(self):
        service = ExtractionService(); mock_data = {'institution': 'DBS', 'account_last4': '553-3', 'currency': 'SGD', 'period_start': '2025-01-01', 'period_end': '2025-01-31', 'opening_balance': '1000.00', 'closing_balance': '1100.00', 'transactions': [{'date': '2025-01-15', 'description': 'Test', 'amount': '100.00', 'direction': 'IN'}]}
        with patch.object(service, 'extract_financial_data', new=AsyncMock(return_value=mock_data)): result = await service.parse_document(DocumentSource.resolve(path=Path('/tmp/test_requires_account.pdf'), content=b'dummy'), institution='DBS', user_id=uuid4())
        assert result.balance_validated is True; assert result.account_last4 == '5533'
class TestDbConstraintVarchar4:
    async def test_direct_write_oversized_account_last4_raises(self, db, test_user):
        stmt = StatementSummaryFactory.build(id=uuid4(), user_id=test_user.id, status=BankStatementStatus.PARSING, file_hash=f'constraint_test_{uuid4().hex[:8]}', institution='DBS', account_last4='553-3'); db.add(stmt)
        with pytest.raises(Exception, match='value too long|StringDataRightTruncation'): await db.flush()
        await db.rollback()
    async def test_exactly_4_chars_accepted(self, db, test_user): stmt = StatementSummaryFactory.build(id=uuid4(), user_id=test_user.id, status=BankStatementStatus.PARSING, file_hash=f'exact4_test_{uuid4().hex[:8]}', institution='DBS', account_last4='5533'); db.add(stmt); await db.commit(); saved = await db.get(StatementSummary, stmt.id); assert saved.account_last4 == '5533'
    async def test_null_account_last4_accepted(self, db, test_user): stmt = StatementSummaryFactory.build(id=uuid4(), user_id=test_user.id, status=BankStatementStatus.PARSING, file_hash=f'null_test_{uuid4().hex[:8]}', institution='DBS', account_last4=None); db.add(stmt); await db.commit(); saved = await db.get(StatementSummary, stmt.id); assert saved.account_last4 is None
class TestBackgroundTaskDirtyData:
    async def test_background_task_with_dirty_account_last4_succeeds(self, db, test_user, monkeypatch):
        from src.database import create_session_maker_from_db; from tests.statement_ingestion import execute_statement_ingestion as parse_statement_background; sid = uuid4(); uid = test_user.id; account = await _make_statement_account(db, uid); stmt = StatementSummaryFactory.build(id=sid, user_id=uid, status=BankStatementStatus.PARSING, file_hash=f'bg_dirty_{uuid4().hex[:8]}', institution='DBS'); db.add(stmt); await db.commit()
        async def mock_parse(*args, **kwargs): source = args[1]; session = kwargs['db']; summary = await session.get(StatementSummary, sid); summary.account_last4 = '5533'; summary.account_id = account.id; summary.currency = 'SGD'; summary.period_start = date(2025, 1, 1); summary.period_end = date(2025, 1, 31); summary.opening_balance = Decimal('1000.00'); summary.closing_balance = Decimal('1000.00'); summary.confidence_score = 90; summary.balance_validated = True; summary.validation_error = None; summary.status = BankStatementStatus.APPROVED; result = build_statement_extraction_result(source=source, file_type='pdf', statement=summary, transactions=[], provider_payload={'transactions': []}, model='fixture-model', provider='fixture-provider', method=ExtractionMethod.GOLDEN_FIXTURE, is_brokerage=False, evidence_type=StatementEvidenceType.TRANSACTION_LEDGER, positions=[]); summary.extraction_metadata = {'statement_extraction_result': result.to_payload()}; await session.flush(); return result
        monkeypatch.setattr('src.extraction.extension.service.ExtractionService.parse_document', mock_parse)
        async def mock_run_in_threadpool(func, *args, **kwargs): return 'https://example.com/presigned'
        monkeypatch.setattr('fastapi.concurrency.run_in_threadpool', mock_run_in_threadpool); await parse_statement_background(job=ParseJob(statement_id=sid, filename='test.pdf', institution='DBS', user_id=uid, account_id=account.id, file_hash=f'bg_dirty_{uuid4().hex[:8]}', storage_key='test_path', model=None), content=b'dummy content', session_maker=create_session_maker_from_db(db)); db.expire_all(); saved = await db.get(StatementSummary, sid); assert saved is not None; assert saved.status == BankStatementStatus.APPROVED; assert saved.account_last4 == '5533'; assert saved.confidence_score == 90; assert saved.balance_validated is True
class TestCascadingFailureRecovery:
    async def test_handle_parse_failure_after_data_error(self, db, test_user):
        from src.extraction.extension.statement_parsing import handle_parse_failure; sid = uuid4(); stmt = StatementSummaryFactory.build(id=sid, user_id=test_user.id, status=BankStatementStatus.PARSING, file_hash=f'cascade_data_{uuid4().hex[:8]}', institution='DBS'); db.add(stmt); await db.commit(); stmt.account_last4 = 'TOOLONG'
        try: await db.flush()
        except Exception: pass
        stub = StatementSummary(id=sid); await handle_parse_failure(stub, db, message='StringDataRightTruncationError: account_last4'); result = await db.get(StatementSummary, sid); assert result is not None; assert result.status == BankStatementStatus.REJECTED; assert 'StringDataRightTruncation' in result.validation_error; assert result.confidence_score == 0
    async def test_handle_parse_failure_after_integrity_error(self, db, test_user):
        from src.extraction.extension.statement_parsing import handle_parse_failure; uid = test_user.id; shared_hash = f'dup_hash_{uuid4().hex[:8]}'; stmt1 = StatementSummaryFactory.build(id=uuid4(), user_id=uid, status=BankStatementStatus.PARSED, file_hash=shared_hash, institution='DBS'); db.add(stmt1); await db.commit(); sid2 = uuid4(); stmt2 = StatementSummaryFactory.build(id=sid2, user_id=uid, status=BankStatementStatus.PARSING, file_hash=f'other_hash_{uuid4().hex[:8]}', institution='DBS'); db.add(stmt2); await db.commit()
        try: await db.execute(text('INSERT INTO nonexistent_cascade_table VALUES (1)'))
        except Exception: pass
        stub2 = StatementSummary(id=sid2); await handle_parse_failure(stub2, db, message='Integrity violation test'); result = await db.get(StatementSummary, sid2); assert result is not None; assert result.status == BankStatementStatus.REJECTED; assert result.validation_error == 'Integrity violation test'
    async def test_background_task_commit_failure_is_retryable(self, db, test_user, monkeypatch):
        from src.extraction import RetryableStatementIngestionError; sid = uuid4(); uid = test_user.id; account = await _make_statement_account(db, uid); stmt = StatementSummaryFactory.build(id=sid, user_id=uid, status=BankStatementStatus.PARSING, file_hash=f'commit_fail_{uuid4().hex[:8]}', institution='DBS'); db.add(stmt); await db.commit(); original_commit = AsyncSession.commit; fail_next_commit = False
        async def conditional_failing_commit(session_self):
            nonlocal fail_next_commit
            if fail_next_commit: fail_next_commit = False; raise RuntimeError('Simulated DB commit failure at finalize step')
            return await original_commit(session_self)
        monkeypatch.setattr(AsyncSession, 'commit', conditional_failing_commit)
        async def parse_then_arm_failure(*args, **kwargs): nonlocal fail_next_commit; source = args[1]; session = kwargs['db']; summary = await session.get(StatementSummary, sid); summary.account_id = account.id; summary.account_last4 = '1234'; summary.currency = 'SGD'; summary.period_start = date(2025, 1, 1); summary.period_end = date(2025, 1, 31); summary.opening_balance = Decimal('1000.00'); summary.closing_balance = Decimal('1100.00'); summary.confidence_score = 90; summary.balance_validated = True; summary.validation_error = None; summary.status = BankStatementStatus.APPROVED; result = build_statement_extraction_result(source=source, file_type='pdf', statement=summary, transactions=[], provider_payload={'transactions': []}, model='fixture-model', provider='fixture-provider', method=ExtractionMethod.GOLDEN_FIXTURE, is_brokerage=False, evidence_type=StatementEvidenceType.TRANSACTION_LEDGER, positions=[]); summary.extraction_metadata = {'statement_extraction_result': result.to_payload()}; await session.flush(); fail_next_commit = True; return result
        monkeypatch.setattr('src.extraction.extension.service.ExtractionService.parse_document', parse_then_arm_failure)
        async def mock_run_in_threadpool(func, *args, **kwargs): return 'https://example.com/presigned'
        monkeypatch.setattr('fastapi.concurrency.run_in_threadpool', mock_run_in_threadpool); from src.database import create_session_maker_from_db; from tests.statement_ingestion import execute_statement_ingestion as parse_statement_background
        with pytest.raises(RetryableStatementIngestionError, match='Simulated DB commit failure'): await parse_statement_background(job=ParseJob(statement_id=sid, filename='test.pdf', institution='DBS', user_id=uid, account_id=account.id, file_hash=f'commit_fail_{uuid4().hex[:8]}', storage_key='test_path', model=None), content=b'dummy content', session_maker=create_session_maker_from_db(db))
        db.expire_all(); saved = await db.get(StatementSummary, sid); assert saved is not None; assert saved.status == BankStatementStatus.PARSING; assert saved.validation_error is None
class TestSanitizeAccountLast4Exhaustive:
    EDGE_CASES = [pytest.param('553-3', '5533', id='production-bug-value'), pytest.param('6789', '6789', id='clean-4-digits'), pytest.param('A', 'A', id='len-1'), pytest.param('AB', 'AB', id='len-2'), pytest.param('ABC', 'ABC', id='len-3'), pytest.param('ABCD', 'ABCD', id='len-4-exact'), pytest.param('ABCDE', 'BCDE', id='len-5-truncates'), pytest.param('A' * 100, 'AAAA', id='len-100-truncates'), pytest.param('1' * 1000, '1111', id='len-1000-truncates'), pytest.param('-', None, id='single-hyphen'), pytest.param('----', None, id='all-hyphens'), pytest.param('...', None, id='dots-only'), pytest.param('!@#$%^&*()', None, id='all-special'), pytest.param('🏦💰', None, id='emoji-only'), pytest.param('\t\n\r', None, id='whitespace-only'), pytest.param('  ', None, id='spaces-only'), pytest.param('A-B-C-D', 'ABCD', id='hyphens-between-each'), pytest.param('---A', 'A', id='leading-hyphens'), pytest.param('A---', 'A', id='trailing-hyphens'), pytest.param('1.2.3.4', '1234', id='dots-between'), pytest.param('(1234)', '1234', id='parentheses'), pytest.param('*5533*', '5533', id='asterisks'), pytest.param('acct#5533', '5533', id='hash-prefix'), pytest.param('１２３４', None, id='fullwidth-digits-stripped'), pytest.param('ＡＢＣＤ', None, id='fullwidth-alpha-stripped'), pytest.param('账户5533', '5533', id='chinese-prefix-stripped'), pytest.param('口座1234', '1234', id='japanese-prefix-stripped'), pytest.param('계좌5533', '5533', id='korean-prefix-stripped'), pytest.param(None, None, id='none'), pytest.param('', None, id='empty'), pytest.param('   ', None, id='spaces-trimmed-empty'), pytest.param('abcd', 'abcd', id='lowercase-preserved'), pytest.param('ABCD', 'ABCD', id='uppercase-preserved'), pytest.param('AbCd', 'AbCd', id='mixed-case-preserved')]
    @pytest.mark.parametrize('input_val,expected', EDGE_CASES)
    def test_sanitize_invariant(self, input_val, expected):
        result = ExtractionService._sanitize_account_last4(input_val); assert result == expected
        if result is not None: assert len(result) <= 4, f"Output '{result}' exceeds 4 chars"; assert result.isalnum(), f"Output '{result}' contains non-alphanumeric chars"
    @pytest.mark.parametrize('random_input', ['a' * i + '-' * j + '1' * k for i in range(0, 4) for j in range(0, 3) for k in range(0, 4)])
    def test_output_never_exceeds_4_chars(self, random_input):
        result = ExtractionService._sanitize_account_last4(random_input); expected_alnum = re.sub('[^a-zA-Z0-9]', '', random_input)
        if expected_alnum: assert result is not None, f"Expected sanitized output for input '{random_input}'"; assert len(result) <= 4; assert result.isalnum(); assert result == expected_alnum[-4:]
        else: assert result is None, f"Expected None for non-alphanumeric input '{random_input}'"
